from solution import fib

import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def ref_fib(n: int) -> int:
    # Obviously-correct iterative reference for standard Fibonacci:
    # F(0)=0, F(1)=1, F(n)=F(n-1)+F(n-2).
    # Pinned by spec examples: F(1)=1, F(8)=21, F(10)=55.
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


# --- explicit spec examples ---

def test_spec_example_fib_10_is_55():
    assert fib(10) == 55


def test_spec_example_fib_1_is_1():
    assert fib(1) == 1


def test_spec_example_fib_8_is_21():
    assert fib(8) == 21


# --- boundary / small values derived from spec's sequence ---

def test_zero_is_zero():
    # n=0 is in-contract (n >= 0) and standard F(0)=0,
    # the only value consistent with F(1)=1, F(8)=21, F(10)=55.
    assert fib(0) == 0


def test_small_table_matches_reference():
    expected = {
        0: 0,
        1: 1,
        2: 1,
        3: 2,
        4: 3,
        5: 5,
        6: 8,
        7: 13,
        8: 21,
        9: 34,
        10: 55,
        11: 89,
        12: 144,
    }
    for n, v in expected.items():
        assert fib(n) == v, f"fib({n})"


def test_returns_int_and_nonnegative():
    for n in range(0, 13):
        v = fib(n)
        assert isinstance(v, int)
        assert v >= 0


# --- property-based tests against reference model ---

@given(st.integers(min_value=0, max_value=15))
def test_equivalence_to_iterative_reference(n):
    assert fib(n) == ref_fib(n)


@given(st.integers(min_value=2, max_value=15))
def test_recurrence_relation(n):
    # Defining invariant of Fibonacci numbers.
    assert fib(n) == fib(n - 1) + fib(n - 2)


@given(st.integers(min_value=0, max_value=14))
def test_monotonic_nondecreasing(n):
    # 0,1,1,2,3,5,... is non-decreasing.
    assert fib(n + 1) >= fib(n)


@given(st.integers(min_value=0, max_value=12))
def test_sum_identity(n):
    # Sum_{i=0..n} F(i) == F(n+2) - 1
    assert sum(fib(i) for i in range(n + 1)) == fib(n + 2) - 1


@given(st.integers(min_value=0, max_value=12))
def test_doubling_identity(n):
    # F(2n) == F(n) * (2*F(n+1) - F(n)); checks global consistency,
    # not just local recurrence.
    assert fib(2 * n) == fib(n) * (2 * fib(n + 1) - fib(n))


@given(st.integers(min_value=1, max_value=12))
def test_gcd_identity(n):
    # gcd(F(m), F(n)) structure: F(n) divides F(2n).
    import math
    assert fib(2 * n) % fib(n) == 0
    assert math.gcd(fib(n), fib(n + 1)) == 1
